277	      templateUrl: './buchung-abrufen-page.html',
278	      styleUrl: './buchung-abrufen-page.scss'
279	    })
280	    export class BuchungAbrufenPage {
281	      private readonly router = inject(Router);
282	      private readonly bookingService = inject(BookingService);
283	
284	      protected readonly reference = signal('');
285	      protected readonly submitting = signal(false);
286	      protected readonly errorMessage = signal<string | null>(null);
287	
288	      protected onReferenceInput(value: string): void {
289	        this.reference.set(value);
290	      }
291	
292	      protected onSubmit(event: Event): void {
293	        event.preventDefault();
294	        const reference = this.reference().trim();
295	        if (!reference) {
296	          this.errorMessage.set('Bitte geben Sie eine Buchungsreferenz ein.');
297	          return;
298	        }
299	
300	        this.errorMessage.set(null);
301	        this.submitting.set(true);
302	
303	        this.bookingService.getBooking(reference).subscribe({
304	          next: (booking) => {
305	            this.submitting.set(false);
306	            this.router.navigate(['/buchungen', reference], { state: { booking } });
307	          },
308	          error: (err: HttpErrorResponse) => {
309	            this.submitting.set(false);
310	            this.errorMessage.set(
311	              err.status === 404
312	                ? 'Keine Buchung mit dieser Referenz gefunden.'
313	                : 'Buchung konnte nicht abgerufen werden. Bitte versuchen Sie es erneut.'
314	            );
315	          }
316	        });
317	      }
318	    }
