    .buchung-detail-page__skeleton-block--total {
      width: 40%;
    }
    ```
    (`--text-meta-size`/`--color-ink-secondary` bereits in `styles.scss` vorhanden, Muster aus `event-card`/`event-detail-page`.)

- [x] **Task 7: Frontend — `SitzplanPage`: `justBooked: true` im Navigations-State ergänzen** (AC: #3 — Regressionsfix für Task 6)
  - [x] `features/sitzplan/sitzplan-page/sitzplan-page.ts`, Zeile ~388 (`onSubmitBooking`-Erfolgszweig): `this.router.navigate(['/buchungen', booking.reference], { state: { booking } });` → `this.router.navigate(['/buchungen', booking.reference], { state: { booking, justBooked: true } });`
    **Warum zwingend:** Task 8 führt eine zweite Quelle für `state.booking` ein (`BuchungAbrufenPage`, reiner Referenz-Abruf, **kein** frischer Abschluss). Ohne explizites `justBooked`-Flag würde `BuchungDetailPage` (Task 6) für **jeden** Zustand mit `state.booking` fälschlich „Buchung bestätigt." anzeigen — auch wenn der Besucher die Buchung nur über die Referenz-Eingabe nachgeschlagen hat. Dieser Einzeiler in bereits bestehendem, funktionierendem Code ist notwendig, um diese Fehlanzeige zu verhindern.

- [x] **Task 8: Frontend — neue Seite `BuchungAbrufenPage` (`/buchungen`) + Routing** (AC: #1, #2)
  - [x] Neuer Ordner `features/buchung/buchung-abrufen-page/` (Feature-Ordner `buchung` bereits durch Story 2.5 angelegt).
  - [x] `buchung-abrufen-page.ts`:
    ```ts
    import { HttpErrorResponse } from '@angular/common/http';
    import { Component, inject, signal } from '@angular/core';
    import { Router } from '@angular/router';

    import { BookingService } from '../../../core/services/booking.service';

    @Component({
      selector: 'app-buchung-abrufen-page',
      imports: [],
      templateUrl: './buchung-abrufen-page.html',
      styleUrl: './buchung-abrufen-page.scss'
    })
    export class BuchungAbrufenPage {
      private readonly router = inject(Router);
      private readonly bookingService = inject(BookingService);

      protected readonly reference = signal('');
      protected readonly submitting = signal(false);
      protected readonly errorMessage = signal<string | null>(null);

      protected onReferenceInput(value: string): void {
        this.reference.set(value);
      }

      protected onSubmit(event: Event): void {
        event.preventDefault();
        const reference = this.reference().trim();
        if (!reference) {
          this.errorMessage.set('Bitte geben Sie eine Buchungsreferenz ein.');
          return;
        }

        this.errorMessage.set(null);
        this.submitting.set(true);

        this.bookingService.getBooking(reference).subscribe({
          next: (booking) => {
            this.submitting.set(false);
            this.router.navigate(['/buchungen', reference], { state: { booking } });
          },
          error: (err: HttpErrorResponse) => {
            this.submitting.set(false);
            this.errorMessage.set(
              err.status === 404
                ? 'Keine Buchung mit dieser Referenz gefunden.'
                : 'Buchung konnte nicht abgerufen werden. Bitte versuchen Sie es erneut.'
            );
          }
        });
      }
    }
    ```
    Navigiert **ohne** `justBooked` (also `false` per `computed()`-Default in Task 6) — bewusst kein "Buchung bestätigt."-Hinweis bei einem regulären Abruf. Übergibt die bereits abgerufene `booking` per `state`, damit `BuchungDetailPage` keinen zweiten `GET`-Request auslöst (identisches Optimierungsmuster wie `SitzplanPage` seit Story 2.5).
  - [x] `buchung-abrufen-page.html` (`mono-reference`-Eingabe + Button, Muster nach `DESIGN.md` Components „Buchungsreferenz-Eingabe", Fehlerzustand mit `danger`-Rahmen und Fehlertext, Muster wie `filter-bar.html`/`summary-panel.html`-Formularfelder):
    ```html
    <h1 class="buchung-abrufen-page__heading">Buchung abrufen</h1>
    <form class="buchung-abrufen-page__form" (submit)="onSubmit($event)">
      <div class="buchung-abrufen-page__field">
        <label class="buchung-abrufen-page__label" for="buchung-abrufen-reference">Buchungsreferenz</label>
        <input
          id="buchung-abrufen-reference"
          class="buchung-abrufen-page__input"
          [class.buchung-abrufen-page__input--invalid]="errorMessage() !== null"
          type="text"
          [value]="reference()"
          (input)="onReferenceInput($any($event.target).value)"
        />
        @if (errorMessage(); as message) {
          <p class="buchung-abrufen-page__field-error">{{ message }}</p>
        }
      </div>
      <button type="submit" class="buchung-abrufen-page__submit" [disabled]="submitting()">
        {{ submitting() ? 'Wird gesucht …' : 'Buchung abrufen' }}
      </button>
    </form>
    ```
  - [x] `buchung-abrufen-page.scss` — `mono-reference`-Rolle auf dem Input (identische Tokens wie `buchung-detail-page__reference`), `[danger]`-Rahmen bei `--invalid`:
    ```scss
    .buchung-abrufen-page__heading {
      font-family: var(--font-display);
      font-size: var(--text-display-sm-size);
