10	@Component({
11	  selector: 'app-buchung-detail-page',
12	  imports: [DatePipe],
13	  templateUrl: './buchung-detail-page.html',
14	  styleUrl: './buchung-detail-page.scss'
15	})
16	export class BuchungDetailPage {
17	  private readonly router = inject(Router);
18	  private readonly bookingService = inject(BookingService);
19	
20	  readonly referenz = input.required<string>();
21	
22	  // Lazy computed() statt eagerly initialisiertem signal(): referenz() ist erst nach
23	  // Konstruktion gesetzt (Router-Input-Binding), ein Zugriff im Field-Initializer würde
24	  // NG0950 auslösen. computed() wertet erst beim ersten Lesen aus.
25	  private readonly navigationState = computed(() => {
26	    const state = this.router.getCurrentNavigation()?.extras.state ?? history.state;
27	    const typed = state as { booking?: Booking; justBooked?: boolean } | undefined;
28	    return typed?.booking && typed.booking.reference === this.referenz()
29	      ? { booking: typed.booking, justBooked: typed.justBooked === true }
30	      : null;
31	  });
32	
33	  private readonly fetchedBooking = signal<Booking | null>(null);
34	  protected readonly loadError = signal<'not-found' | 'failed' | null>(null);
35	
36	  protected readonly booking = computed<Booking | null>(() => this.navigationState()?.booking ?? this.fetchedBooking());
37	  protected readonly justBooked = computed(() => this.navigationState()?.justBooked === true);
38	  protected readonly copied = signal(false);
39	
40	  protected readonly formatEuroAmount = formatEuroAmount;
41	
42	  constructor() {
43	    effect((onCleanup) => {
44	      if (this.navigationState()) {
45	        return;
46	      }
47	
48	      this.fetchedBooking.set(null);
49	      this.loadError.set(null);
50	
