    }

    .status-badge--cancelled {
      color: var(--color-ink-secondary);
      text-decoration: line-through;
    }
    ```
  - [ ] `status-badge.spec.ts` (neu, Muster wie `error-banner.spec.ts`): rendert „aktiv" ohne `--cancelled`-Klasse bei `status: 'Active'`; rendert „storniert" mit `--cancelled`-Klasse bei `status: 'Cancelled'`.

- [ ] **Task 6: Frontend — neue Component `CancelDialog`** (AC: #1)
  - [ ] Neuer Ordner `features/buchung/cancel-dialog/` (nur von `BuchungDetailPage` verwendet, daher Feature-lokal statt `shared/` — Muster konsistent mit `features/sitzplan/summary-panel/`, ebenfalls nur an einer Stelle verwendet).
  - [ ] `cancel-dialog.ts`:
    ```ts
    import { Component, HostListener, input, output } from '@angular/core';

    @Component({
      selector: 'app-cancel-dialog',
      imports: [],
      templateUrl: './cancel-dialog.html',
      styleUrl: './cancel-dialog.scss'
    })
    export class CancelDialog {
      readonly cancelling = input<boolean>(false);
      readonly confirm = output<void>();
      readonly cancel = output<void>();

      @HostListener('document:keydown.escape')
      protected onEscape(): void {
        this.cancel.emit();
